1	package cli
2	
3	import (
4		"context"
5		"database/sql"
6		"fmt"
7		"github.com/entireio/entire-brain/internal/cli/internal/brainstore"
8		"github.com/entireio/entire-brain/internal/cli/internal/cmdutil"
9		"io"
10		"os"
11		"sort"
12		"strings"
13	
14		"github.com/entireio/entire-brain/internal/cli/internal/base"
15		bmanifest "github.com/entireio/entire-brain/internal/cli/internal/manifest"
16		patterncore "github.com/entireio/entire-brain/internal/cli/patterns"
17		"github.com/spf13/cobra"
18	)
19	
20	// patterns command surface (Pattern Consolidation, Phase 1).
21	//
22	// Public, job-oriented commands per the plan: `patterns refresh` rebuilds the
23	// derived layer, `patterns status` reports freshness and counts. The bare
24	// `patterns` command is a read-only default — in Phase 1 it shows status; the
25	// strongest-patterns listing arrives with procedure detection (Phase 2).
26	
27	func newPatternsCommand(opts Options) *cobra.Command {
28		var listOpts patternsListOptions
29		cmd := &cobra.Command{
30			Use:     "patterns [path]",
31			Short:   "Inspect and rebuild recurring patterns from sessions",
32			Long:    "Inspect and rebuild repeated-work patterns derived from session history",
33			GroupID: "create",
34			Args:    cobra.MaximumNArgs(1),
35			RunE: func(cmd *cobra.Command, args []string) error {
36				return runPatternsList(cmd.Context(), cmd, opts, targetFromArgs(opts, args), listOpts)
37			},
38		}
39		cmd.Flags().BoolVar(&listOpts.asJSON, "json", false, "Emit patterns as JSON")
40		cmd.Flags().IntVar(&listOpts.limit, "limit", 20, "Maximum number of patterns to show")
41		cmd.Flags().StringVar(&listOpts.typ, "type", "", "Filter by type: task|procedure|risk|practice|theme")
42		cmd.Flags().StringVar(&listOpts.scope, "scope", "", "Filter by scope: repo|workspace")
43		cmd.AddCommand(newPatternsRefreshCommand(opts))
44		cmd.AddCommand(newPatternsStatusCommand(opts))
45		cmd.AddCommand(newPatternsVerifyCommand(opts))
46		cmd.AddCommand(newPatternsSkillsCommand(opts))
47		return cmd
48	}
49	
50	type patternsListOptions struct {
51		asJSON bool
52		limit  int
53		typ    string
54		scope  string
55	}
56	
57	func runPatternsList(ctx context.Context, cmd *cobra.Command, opts Options, target string, listOpts patternsListOptions) error {
58		brainDir, err := resolvePatternsBrainDir(ctx, opts, target)
59		if err != nil {
60			return err
61		}
62		privacyPolicy, err := brainstore.CaptureRetrievalPrivacyPolicy(brainDir)
63		if err != nil {
64			return err
65		}
66		privacyPolicy.RequireDerivedClean = true
67		if err := requirePrivacyDerivedRead(brainDir); err != nil {
68			return err
69		}
70		// Primary analytical source is the V2 corpus; the legacy procedure/practice
71		// JSON views remain only as a fallback when no corpus has been built yet.
72		views, _, corpusBacked, err := loadCorpusPatternViewsChecked(brainDir)
73		if err != nil {
74			return err
75		}
76		if !corpusBacked {
77			var verr error
78			if views, _, verr = loadPatternViews(brainDir); verr != nil {
79				return verr
80			}
81		} else {
82			// Themes are a verifier-gated channel: only verified-accepted themes
83			// surface (matching brief/overview and the stated contract). Unverified
84			// candidates are processed by `patterns verify --themes`, not listed here.
85			themes, err := loadThemeViewsChecked(brainDir, true)
86			if err != nil {
87				return err
88			}
89			for _, th := range themes {
90				views = append(views, themePatternView(th))
91			}
92		}
93		memoryRecords, err := loadBrainSkillMemory(brainDir)
94		if err != nil {
95			return err
96		}
97		memIdx := skillMemoryByPatternID(memoryRecords)
98	
99		filtered := views[:0:0]
100		for _, v := range views {
101			if listOpts.typ != "" && v.Type != listOpts.typ {
102				continue
103			}
104			if listOpts.scope != "" && v.Scope != listOpts.scope {
105				continue
106			}
107			// Skill-memory recommendation: suppress already-formed-and-current and
108			// declined-and-unchanged patterns; annotate the rest that have a decision.
109			if rec, ok := memIdx[v.ID]; ok {
110				eval := evaluateSkillMemory(rec, &v)
111				if eval.suppressInListing() {
112					continue
113				}
114				v.SkillStatus = eval.Status + "/" + eval.Sub
115				v.Note = eval.annotation()
116			}
117			filtered = append(filtered, v)
118		}
119		sort.SliceStable(filtered, func(i, j int) bool { return filtered[i].Strength > filtered[j].Strength })
120		if listOpts.limit > 0 && len(filtered) > listOpts.limit {
121			filtered = filtered[:listOpts.limit]
122		}
123		patternsPresent := true
124		if len(filtered) == 0 {
125			status, err := buildPatternsStatusReportChecked(brainDir)
126			if err != nil {
127				return err
128			}
129			patternsPresent = status.Present
130		}
131	
132		return bufferRetrievalCommandOutput(cmd, []retrievalPrivacyPolicy{privacyPolicy}, func() error {
133			if listOpts.asJSON {
134				return cmdutil.WriteJSON(cmd, filtered)
135			}
136			out := cmd.OutOrStdout()
137			if len(filtered) == 0 {
138				if !patternsPresent {
139					fmt.Fprintln(out, "patterns: not built (run `"+base.BrainInvocation(os.LookupEnv, "patterns refresh")+"`)")
140				} else {
141					fmt.Fprintln(out, "patterns: none detected yet")
142				}
143				return nil
144			}
145			for _, v := range filtered {
146				renderPatternView(out, v)
147			}
148			return nil
149		})
150	}
151	
152	// patternView is the unified listing shape for both pattern families, so
153	// procedures and practices sort and render through one path.
154	type patternView struct {
155		ID            string               `json:"id"`
156		Type          string               `json:"type"`
157		Scope         string               `json:"scope"`
158		Kind          string               `json:"kind,omitempty"`
159		Title         string               `json:"title"`
160		Strength      float64              `json:"strength"`
161		StrengthLabel string               `json:"strength_label"`
162		Support       int                  `json:"support"`
163		Repos         int                  `json:"repos,omitempty"`          // workspace scope
164		RepoBreakdown []patternRepoStat    `json:"repo_breakdown,omitempty"` // workspace scope
165		Reinforcement *reinforcementCounts `json:"reinforcement,omitempty"`
166		Example       *episodeAnchor       `json:"example,omitempty"`
167		SkillStatus   string               `json:"skill_status,omitempty"` // e.g. "active/update", "declined/reconsider"
168		Note          string               `json:"note,omitempty"`         // human-readable recommendation
169		// V2 corpus-backed fields (empty for legacy views).
170		IntentSig     string `json:"intent_sig,omitempty"`
171		Gram          string `json:"gram,omitempty"`
172		DossierStatus string `json:"dossier_status,omitempty"` // current | stale (promotable patterns only)
173		Verdict       string `json:"verdict,omitempty"`        // accepted | needs_split | low_confidence (rejected are suppressed)
174		Workspace     string `json:"workspace,omitempty"`
175	}
176	
177	// loadPatternViews loads procedures + practices as unified views and an index by
178	// pattern id.
179	func loadPatternViews(brainDir string) ([]patternView, map[string]patternView, error) {
180		procedures, err := loadBrainProcedures(brainDir)
181		if err != nil {
182			return nil, nil, err
183		}
184		practices, err := loadBrainPractices(brainDir)
185		if err != nil {
186			return nil, nil, err
187		}
188		views := make([]patternView, 0, len(procedures)+len(practices))
189		for _, p := range procedures {
190			views = append(views, procedureView(p))
191		}
192		for _, p := range practices {
193			views = append(views, practiceView(p))
194		}
195		idx := make(map[string]patternView, len(views))
196		for _, v := range views {
197			idx[v.ID] = v
198		}
199		return views, idx, nil
200	}
201	
202	// strongestPatterns loads the top-N patterns by strength for the overview.
203	func strongestPatterns(brainDir string, limit int) []patternView {
204		views, _ := strongestPatternsChecked(brainDir, limit)
205		return views
206	}
207	
208	func strongestPatternsChecked(brainDir string, limit int) ([]patternView, error) {
209		views, _, err := loadPatternViews(brainDir)
210		if err != nil {
211			return nil, err
212		}
213		if len(views) == 0 {
214			return nil, nil
215		}
216		sort.SliceStable(views, func(i, j int) bool { return views[i].Strength > views[j].Strength })
217		if limit > 0 && len(views) > limit {
218			views = views[:limit]
219		}
220		return views, nil
221	}
222	
223	// brainBriefPatternsCount caps how many task-relevant patterns the brief carries.
224	func brainBriefPatternsCount(limit int) int {
225		if limit <= 0 || limit > 5 {
226			return 5
227		}
228		return limit
229	}
230	
231	// rankTaskRelevantPatterns returns the patterns whose title/kind share a term
232	// with the task, ranked by term overlap then strength. Patterns with no overlap
233	// are dropped — the brief should surface task-relevant patterns, not ambient
234	// noise — so an unrelated task yields none.
235	func rankTaskRelevantPatterns(views []patternView, terms []string, limit int) []patternView {
236		if limit <= 0 || len(terms) == 0 {
237			return nil
238		}
239		termSet := make(map[string]bool, len(terms))
240		for _, t := range terms {
241			termSet[t] = true
242		}
243		type scored struct {
244			v       patternView
245			overlap int
246		}
247		var matched []scored
248		for _, v := range views {
249			seen := map[string]bool{}
250			overlap := 0
251			for _, w := range brainBriefTaskWordPattern.FindAllString(strings.ToLower(v.Title+" "+v.Kind), -1) {
252				if termSet[w] && !seen[w] {
253					seen[w] = true
254					overlap++
255				}
256			}
257			if overlap > 0 {
258				matched = append(matched, scored{v, overlap})
259			}
260		}
261		sort.SliceStable(matched, func(i, j int) bool {
262			if matched[i].overlap != matched[j].overlap {
263				return matched[i].overlap > matched[j].overlap
264			}
265			return matched[i].v.Strength > matched[j].v.Strength
266		})
267		out := make([]patternView, 0, limit)
268		for _, m := range matched {
269			if len(out) >= limit {
270				break
271			}
272			out = append(out, m.v)
273		}
274		return out
275	}
