316	// renderPatternView prints a concise read-only pattern card. Patterns are
317	// diagnostic; the evidence-first approval card lives in `patterns skills form`.
318	func renderPatternView(out io.Writer, v patternView) {
319		label := v.Type
320		if v.Kind != "" {
321			label += "/" + v.Kind
322		}
323		scope := v.Scope
324		if v.Scope == "workspace" && v.Workspace != "" {
325			scope = "workspace:" + v.Workspace
326		}
327		state := v.DossierStatus
328		if v.Verdict != "" {
329			state = strings.TrimLeft(state+"/"+v.Verdict, "/")
330		}
331		header := fmt.Sprintf("[%s] %s  (%s", strings.ToUpper(v.StrengthLabel), base.RedactText(v.Title), label)
332		if scope != "" {
333			header += ", " + scope
334		}
335		header += fmt.Sprintf(", strength %.2f", v.Strength)
336		if state != "" {
337			header += ", " + state
338		}
339		header += ")"
340		fmt.Fprintln(out, header)
341		if v.Reinforcement != nil {
342			r := v.Reinforcement
343			fmt.Fprintf(out, "    seen in %d episode(s); reinforcement %d↑ %d↓ %d·\n", v.Support, r.Success, r.Corrected, r.Neutral)
344		} else {
345			fmt.Fprintf(out, "    seen in %d session(s)\n", v.Support)
346		}
347		if v.Scope == "workspace" && v.Repos > 0 {
348			repos := make([]string, 0, len(v.RepoBreakdown))
349			for _, b := range v.RepoBreakdown {
350				repos = append(repos, fmt.Sprintf("%s(%d)", b.RepoKey, b.Support))
351			}
352			fmt.Fprintf(out, "    across %d repo(s): %s\n", v.Repos, strings.Join(repos, ", "))
353		}
354		if v.Example != nil {
355			fmt.Fprintf(out, "    e.g. %s:%d   id %s\n", base.RedactText(v.Example.Path), v.Example.Line, v.ID)
356		} else {
357			fmt.Fprintf(out, "    id %s\n", v.ID)
358		}
359		if v.Note != "" {
360			fmt.Fprintf(out, "    ! %s\n", v.Note)
361		}
362	}
