432	func runPatternsVerify(ctx context.Context, cmd *cobra.Command, opts Options, target, agent, model, effort string, asJSON, deep, themes, lessons, conventions bool) error {
433		repoDir, brainDir, err := resolvePatternsRepoAndBrain(ctx, opts, target)
434		if err != nil {
435			return err
436		}
437		privacyPolicy, err := brainstore.CaptureRetrievalPrivacyPolicy(brainDir)
438		if err != nil {
439			return err
440		}
441		privacyPolicy.RequireDerivedClean = true
442		if err := requirePrivacyDerivedRead(brainDir); err != nil {
443			return err
444		}
445		if err := base.RejectAgentForNoEgress(agent); err != nil {
446			return err
447		}
448		return runPrivacyLinearizedPatternMutation(cmd, []retrievalPrivacyPolicy{privacyPolicy}, func() error {
449			run := defaultDistillAgentRunner(agent)
450			verify := patterncore.VerifyDossiers
451			mode := "dossier"
452			switch {
453			case themes:
454				verify = verifyThemes
455				mode = "theme"
456			case lessons:
457				verify = proposeSkillLessons
458				mode = "lesson"
459			case conventions:
460				verify = proposeSkillConventions
461				mode = "convention"
462			case deep:
463				verify = verifyDeepDossiers
464				mode = "deep dossier"
465			}
466			var stats patterncore.VerifyStats
467			if err := patterncore.WithCorpusMutationLocked(brainDir, func(db *sql.DB) error {
468				var verifyErr error
469				stats, verifyErr = verify(ctx, db, brainDir, repoDir, agent, model, effort, run, opts.Now().UTC())
470				return verifyErr
471			}, patterncore.DecodeCorpusPublication); err != nil {
472				return err
473			}
474			if asJSON {
475				return cmdutil.WriteJSON(cmd, stats)
476			}
477			fmt.Fprintf(cmd.OutOrStdout(), "patterns verify: %d %s(s) — %d verified, %d cached, %d failed\n",
478				stats.Considered, mode, stats.Verified, stats.Cached, stats.Failed)
479			return nil
480		})
481	}
