601	// buildPatternsStatusReport reads the patterns source from the manifest and
602	// derives freshness from its recorded inputs — the sessions fingerprint and the
603	// tombstone epoch — via patternSourceCurrent, the same predicate the refresh
604	// trigger uses, so no re-extraction is required and the two cannot disagree.
605	// Skill-memory counts are computed by evaluating each user decision against the
606	// current pattern set.
607	func buildPatternsStatusReport(brainDir string) patternsStatusReport {
608		report, _ := buildPatternsStatusReportChecked(brainDir)
609		return report
610	}
611	
612	func buildPatternsStatusReportChecked(brainDir string) (patternsStatusReport, error) {
613		manifest, err := bmanifest.Load(brainDir)
614		if err != nil {
615			return patternsStatusReport{}, err
616		}
617		lastRun, hasLastRun, err := patterncore.LastRunChecked(brainDir)
618		if err != nil {
619			return patternsStatusReport{}, err
620		}
621		_, byID, err := loadPatternViews(brainDir)
622		if err != nil {
623			return patternsStatusReport{}, err
624		}
625		memoryRecords, err := loadBrainSkillMemory(brainDir)
626		if err != nil {
627			return patternsStatusReport{}, err
628		}
629		if manifest.Sources == nil || manifest.Sources.Patterns == nil {
630			return patternsStatusReport{Present: false, Freshness: "missing"}, nil
631		}
632		src := manifest.Sources.Patterns
633		freshness := "current"
634		if !patternSourceCurrent(src, brainDir) {
635			freshness = "stale"
636		}
637		rc := src.Reinforcement
638		report := patternsStatusReport{
639			Present:       true,
640			Freshness:     freshness,
641			Episodes:      src.Episodes,
642			Reinforcement: &rc,
643			Procedures:    src.Procedures,
644			Practices:     src.Practices,
645			Patterns:      src.Patterns,
646		}
647		if hasLastRun {
648			report.LastRun = &lastRun
649		}
650	
651		for _, rec := range memoryRecords {
652			var cur *patternView
653			if v, ok := byID[rec.PatternID]; ok {
654				cur = &v
655			}
656			eval := evaluateSkillMemory(rec, cur)
657			if eval.Status == skillStatusDeclined {
658				report.DeclinedPatterns++
659			} else {
660				report.AcceptedSkills++
661			}
662			if eval.needsAttention() {
663				report.UpdatesAvailable++
664			}
665		}
666		return report, nil
667	}
