16	// Pattern corpus surface integration (V2, Phase 5).
17	//
18	// Read-only projections of the corpus dossiers into existing brain surfaces.
19	// Everything here is best-effort and graceful: a missing/!built corpus yields no
20	// rows (never an error that breaks brief/get), output is already redacted at
21	// rest, and a verifier `rejected` verdict suppresses a consolidation entirely —
22	// the agent verifier is the authority that can remove, the deterministic gate the
23	// authority that promotes.
24	
25	// loadCorpusPatternViews lists the V2 corpus `patterns` rows as unified
26	// patternViews — the primary analytical source for the public `patterns`
27	// surface (replacing the legacy procedure/practice JSON views). Each view
28	// carries its dossier state (current/stale + verifier verdict) and top anchor.
29	// Rejected dossiers are suppressed. Graceful: nil when no corpus exists.
30	func loadCorpusPatternViewsChecked(brainDir string) ([]patternView, map[string]patternView, bool, error) {
31		db, present, err := patterncore.OpenCorpusReadDBIfPresent(brainDir)
32		if err != nil {
33			return nil, nil, false, err
34		}
35		if !present {
36			return nil, nil, false, nil
37		}
38		defer db.Close()
39	
40		anchors, err := topAnchorByPatternChecked(db.DB)
41		if err != nil {
42			return nil, nil, true, err
43		}
44		rows, err := db.Query(`
45			SELECT p.id, p.type, p.scope, COALESCE(p.repo_key,''), COALESCE(p.workspace,''),
46			       COALESCE(p.intent_sig,''), COALESCE(p.gram,''), COALESCE(p.meta_id,''),
47			       p.title, p.strength, p.strength_label, p.support, p.n_repos,
48			       p.outcome_success, p.outcome_corrected, p.outcome_neutral,
49			       COALESCE(d.status,''), COALESCE(d.verdict,'')
50			FROM patterns p
51			LEFT JOIN dossiers d ON d.pattern_id = p.id
52			ORDER BY p.strength DESC`)
53		if err != nil {
54			return nil, nil, true, err
55		}
56		defer rows.Close()
57		var views []patternView
58		for rows.Next() {
59			var (
60				v                          patternView
61				repoKey, workspace, metaID string
62				succ, corr, neutral        int
63				dossierStatus, verdict     string
64			)
65			if err := rows.Scan(&v.ID, &v.Type, &v.Scope, &repoKey, &workspace,
66				&v.IntentSig, &v.Gram, &metaID, &v.Title, &v.Strength, &v.StrengthLabel, &v.Support, &v.Repos,
67				&succ, &corr, &neutral, &dossierStatus, &verdict); err != nil {
68				return nil, nil, true, err
69			}
70			if verdict == "rejected" { // the agent verifier is the authority that removes
71				continue
72			}
73			v.Kind = metaID
74			v.Workspace = workspace
75			v.Title = base.RedactText(v.Title)
76			v.DossierStatus = dossierStatus
77			v.Verdict = verdict
78			rc := reinforcementCounts{Success: succ, Corrected: corr, Neutral: neutral}
79			v.Reinforcement = &rc
80			if a, ok := anchors[v.ID]; ok {
81				ca := a
82				v.Example = &ca
83			}
84			views = append(views, v)
85		}
86		if rows.Err() != nil {
87			return nil, nil, true, rows.Err()
88		}
89		// Attach the per-repo breakdown to workspace-scope patterns.
90		breakdown, err := patterncore.LoadWorkspaceRepoBreakdownChecked(db.DB)
91		if err != nil {
92			return nil, nil, true, err
93		}
94		for i := range views {
95			if views[i].Scope == "workspace" {
96				views[i].RepoBreakdown = breakdown[views[i].ID]
97			}
98		}
99		idx := make(map[string]patternView, len(views))
100		for _, v := range views {
101			idx[v.ID] = v
102		}
103		return views, idx, true, nil
104	}
