198	// rankTaskRelevantConsolidations returns the dossiers whose title/trigger/
199	// workflow share a term with the task, ranked by overlap then confidence, capped.
200	// Rejected consolidations are suppressed; unrelated tasks yield none (no ambient
201	// noise — the same discipline as rankTaskRelevantPatterns).
202	func rankTaskRelevantConsolidations(dossiers []loadedDossier, terms []string, limit int) []briefConsolidation {
203		if limit <= 0 || len(terms) == 0 {
204			return nil
205		}
206		termSet := make(map[string]bool, len(terms))
207		for _, t := range terms {
208			termSet[t] = true
209		}
210		type scored struct {
211			c       briefConsolidation
212			overlap int
213		}
214		var matched []scored
215		for _, d := range dossiers {
216			if d.verdict == "rejected" {
217				continue
218			}
219			hay := strings.ToLower(d.rec.Title + " " + d.rec.Trigger + " " + strings.Join(d.rec.Workflow, " "))
220			seen := map[string]bool{}
221			overlap := 0
222			for _, w := range brainBriefTaskWordPattern.FindAllString(hay, -1) {
223				if termSet[w] && !seen[w] {
224					seen[w] = true
225					overlap++
226				}
227			}
228			if overlap == 0 {
229				continue
230			}
231			matched = append(matched, scored{consolidationView(d), overlap})
232		}
233		sort.SliceStable(matched, func(i, j int) bool {
234			if matched[i].overlap != matched[j].overlap {
235				return matched[i].overlap > matched[j].overlap
236			}
237			return matched[i].c.Confidence > matched[j].c.Confidence
238		})
239		out := make([]briefConsolidation, 0, limit)
240		for _, m := range matched {
241			if len(out) >= limit {
242				break
243			}
244			out = append(out, m.c)
245		}
246		return out
247	}
