403	func loadReviewPatternContextChecked(brainDir string, files []string, limit int) ([]reviewPatternRef, error) {
404		if len(files) == 0 || limit <= 0 {
405			return nil, nil
406		}
407		db, present, err := patterncore.OpenCorpusReadDBIfPresent(brainDir)
408		if err != nil {
409			return nil, err
410		}
411		if !present {
412			return nil, nil
413		}
414		defer db.Close()
415		ph := make([]string, len(files))
416		args := make([]any, 0, len(files)+1)
417		for i, f := range files {
418			ph[i] = "?"
419			args = append(args, f)
420		}
421		args = append(args, limit*4)
422		rows, err := db.Query(`
423			SELECT DISTINCT p.id, p.type, p.title, ef.path
424			FROM patterns p
425			JOIN pattern_evidence pe ON pe.pattern_id = p.id
426			JOIN episode_files ef ON ef.episode_id = pe.episode_id
427			LEFT JOIN dossiers d ON d.pattern_id = p.id
428			WHERE p.type IN ('risk','practice','task')
429			  AND COALESCE(d.verdict,'') != 'rejected'
430			  AND ef.path IN (`+strings.Join(ph, ",")+`)
431			ORDER BY p.strength DESC LIMIT ?`, args...)
432		if err != nil {
433			return nil, err
434		}
435		defer rows.Close()
436		var out []reviewPatternRef
437		seen := map[string]bool{}
438		for rows.Next() {
439			var id, typ, title, path string
440			if err := rows.Scan(&id, &typ, &title, &path); err != nil {
441				return out, err
442			}
443			key := id + "\x00" + path
444			if seen[key] {
445				continue
446			}
447			seen[key] = true
448			if len(out) >= limit {
449				break
450			}
451			out = append(out, reviewPatternRef{File: base.RedactText(path), Type: typ, Title: base.RedactText(title), ID: id})
452		}
453		return out, rows.Err()
454	}
