522	func renderConsolidationText(rec patterncore.DossierRecord, status, verdict string) string {
523		var b strings.Builder
524		b.WriteString(rec.Title)
525		b.WriteString("\n")
526		if rec.Trigger != "" {
527			b.WriteString("trigger: " + rec.Trigger + "\n")
528		}
529		if len(rec.Workflow) > 0 {
530			b.WriteString("workflow: " + strings.Join(rec.Workflow, " → ") + "\n")
531		}
532		if len(rec.Verification) > 0 {
533			b.WriteString("verify: " + strings.Join(rec.Verification, ", ") + "\n")
534		}
535		if len(rec.FailureModes) > 0 {
536			b.WriteString("failure modes: " + strings.Join(rec.FailureModes, "; ") + "\n")
537		}
538		if len(rec.Facts) > 0 {
539			b.WriteString("facts: " + strings.Join(rec.Facts, "; ") + "\n")
540		}
541		state := status
542		if verdict != "" {
543			state += ", verdict=" + verdict
544		}
545		b.WriteString("confidence ")
546		b.WriteString(strconv.FormatFloat(rec.Confidence, 'g', -1, 64))
547		b.WriteString(" (" + state + ")")
548		// Already redacted at rest; defensive redaction on egress.
549		return base.RedactText(b.String())
550	}
