19	//
20	// Skill memory is USER STATE — the record of which patterns the user has formed
21	// into skills or declined. Unlike episodes/procedures/practices it is NOT
22	// rebuilt by refresh (refresh never writes this file), so a decision survives
23	// every rebuild. The link is the pattern id, which is a stable content hash, so
24	// linkage holds even as the derived layer is regenerated.
25	//
26	// This phase establishes the record, its persistence, the state machine, and the
27	// recommendations surfaced in `patterns` / `patterns status`. Records are created
28	// by `patterns skills form`; here they are read and evaluated.
29	
30	const patternsSkillMemoryPath = "patterns/skill-memory.ndjson"
31	
32	const (
33		skillStatusActive   = "active"
34		skillStatusDeclined = "declined"
35	)
36	
37	// sub-states derived from comparing the recorded decision against the current
38	// evidence and the on-disk skill files.
39	const (
40		skillSubCurrent    = "current"    // accepted & unchanged, or declined & unchanged
41		skillSubUpdate     = "update"     // evidence changed materially since the decision
42		skillSubEdited     = "edited"     // a written skill file changed since formation
43		skillSubMissing    = "missing"    // a recorded skill file is gone
44		skillSubReconsider = "reconsider" // declined, but evidence changed materially
45	)
46	
47	type skillInstall struct {
48		Agents     []string `json:"agents,omitempty"`
49		Path       string   `json:"path"`
50		ContentSHA string   `json:"content_sha,omitempty"`
51	}
52	
53	type skillMemoryRecord struct {
54		PatternID     string              `json:"pattern_id"`
55		Scope         string              `json:"scope,omitempty"`
56		Status        string              `json:"status"` // active | declined
57		SkillName     string              `json:"skill_name,omitempty"`
58		Installs      []skillInstall      `json:"installs,omitempty"`
59		Fingerprint   string              `json:"fingerprint,omitempty"` // evidence fingerprint at decision time
60		Support       int                 `json:"support,omitempty"`
61		Reinforcement reinforcementCounts `json:"reinforcement,omitempty"`
62		CreatedAt     time.Time           `json:"created_at"`
63		UpdatedAt     time.Time           `json:"updated_at"`
64		Note          string              `json:"note,omitempty"`
65	}
66	
67	// skillMemoryEval is the derived recommendation for one record against the
68	// current pattern set.
69	type skillMemoryEval struct {
70		Status string // active | declined
71		Sub    string // current | update | edited | missing | reconsider
72	}
73	
74	// suppressInListing reports whether a pattern with this evaluation should be
75	// hidden from the default proposal listing — an already-formed-and-current skill
76	// or a declined-and-unchanged pattern is not re-proposed.
77	func (e skillMemoryEval) suppressInListing() bool {
78		return e.Sub == skillSubCurrent
79	}
80	
81	// needsAttention reports whether the record should count toward "updates
82	// available": an accepted skill whose evidence/file drifted, or a declined
83	// pattern whose evidence changed enough to reconsider.
84	func (e skillMemoryEval) needsAttention() bool {
85		switch e.Sub {
86		case skillSubUpdate, skillSubEdited, skillSubMissing, skillSubReconsider:
87			return true
88		}
89		return false
90	}
91	
92	func (e skillMemoryEval) annotation() string {
93		switch e.Sub {
94		case skillSubUpdate:
95			return "skill exists — evidence changed, update available"
96		case skillSubEdited:
97			return "skill edited since formation — review before update"
98		case skillSubMissing:
99			return "skill file missing — recreate or forget"
100		case skillSubReconsider:
101			return "previously declined — evidence changed"
102		}
103		return ""
104	}
105	
106	// evaluateSkillMemory derives the recommendation for a record. current is the
107	// pattern's present view, or nil when the pattern no longer surfaces.
108	func evaluateSkillMemory(rec skillMemoryRecord, current *patternView) skillMemoryEval {
109		changed := current != nil && rec.Fingerprint != "" && patternEvidenceFingerprint(*current) != rec.Fingerprint
110	
111		if rec.Status == skillStatusDeclined {
112			if changed {
113				return skillMemoryEval{Status: skillStatusDeclined, Sub: skillSubReconsider}
114			}
115			return skillMemoryEval{Status: skillStatusDeclined, Sub: skillSubCurrent}
116		}
117	
118		// active: file integrity takes precedence over evidence drift — a gone or
119		// hand-edited file is the more urgent signal.
120		for _, in := range rec.Installs {
121			sha, ok := fileContentSHA(in.Path)
122			if !ok {
123				return skillMemoryEval{Status: skillStatusActive, Sub: skillSubMissing}
124			}
125			if in.ContentSHA != "" && sha != in.ContentSHA {
126				return skillMemoryEval{Status: skillStatusActive, Sub: skillSubEdited}
127			}
128		}
129		if changed {
130			return skillMemoryEval{Status: skillStatusActive, Sub: skillSubUpdate}
131		}
132		return skillMemoryEval{Status: skillStatusActive, Sub: skillSubCurrent}
133	}
134	
135	// patternEvidenceFingerprint captures a pattern's *material* evidence so a minor
136	// drift (one more supporting episode) does not read as a change while a strength
137	// re-tier or a support-magnitude jump does. Excludes identity (the id already
138	// pins that) and volatile exact counts.
139	func patternEvidenceFingerprint(v patternView) string {
140		net := 0
141		if v.Reinforcement != nil {
142			net = sign(v.Reinforcement.Success - v.Reinforcement.Corrected)
143		}
144		bucket := int(math.Log2(float64(1 + v.Support)))
145		payload := fmt.Sprintf("%s\x00%s\x00%s\x00%d\x00%d", v.Type, v.Scope, v.StrengthLabel, bucket, net)
146		sum := sha256.Sum256([]byte(payload))
147		return "sha256:" + hex.EncodeToString(sum[:])
148	}
149	
150	func sign(n int) int {
151		switch {
152		case n > 0:
153			return 1
154		case n < 0:
155			return -1
156		default:
157			return 0
158		}
159	}
160	
161	// fileContentSHA returns the sha256 of a (possibly ~-prefixed) file's content
162	// and whether it could be read.
163	func fileContentSHA(path string) (string, bool) {
164		data, err := os.ReadFile(expandHomePath(path))
165		if err != nil {
166			return "", false
167		}
168		sum := sha256.Sum256(data)
169		return "sha256:" + hex.EncodeToString(sum[:]), true
170	}
171	
172	func expandHomePath(path string) string {
173		if path == "~" || strings.HasPrefix(path, "~/") {
174			if home, err := os.UserHomeDir(); err == nil {
175				return filepath.Join(home, strings.TrimPrefix(strings.TrimPrefix(path, "~"), "/"))
176			}
177		}
178		return path
179	}
180	
181	// loadBrainSkillMemory reads the user-state skill memory. Missing file -> empty.
182	func loadBrainSkillMemory(brainDir string) ([]skillMemoryRecord, error) {
183		content, err := readBrainRelativeStateFile(brainDir, patternsSkillMemoryPath)
184		if err != nil {
185			if errors.Is(err, os.ErrNotExist) {
186				return nil, nil
187			}
188			return nil, err
189		}
190		var records []skillMemoryRecord
191		for _, line := range strings.Split(content, "\n") {
192			line = strings.TrimSpace(line)
193			if line == "" {
194				continue
195			}
196			var r skillMemoryRecord
197			if err := json.Unmarshal([]byte(line), &r); err != nil {
198				return nil, fmt.Errorf("parse skill-memory line: %w", err)
199			}
200			records = append(records, r)
201		}
202		return records, nil
203	}
204	
205	// skillMemoryByPatternID indexes records by pattern id (last write wins).
206	func skillMemoryByPatternID(records []skillMemoryRecord) map[string]skillMemoryRecord {
207		out := make(map[string]skillMemoryRecord, len(records))
208		for _, r := range records {
209			out[r.PatternID] = r
210		}
211		return out
212	}
213	
214	// writeBrainSkillMemory persists the user-state skill memory atomically. Refresh
215	// never calls this; only the skill-creation surface (`patterns skills form`) does.
216	func writeBrainSkillMemory(brainDir string, records []skillMemoryRecord) error {
217		var buf bytes.Buffer
218		enc := json.NewEncoder(&buf)
219		enc.SetEscapeHTML(false)
220		for _, r := range records {
221			if err := enc.Encode(r); err != nil {
222				return fmt.Errorf("encode skill-memory: %w", err)
223			}
224		}
225		if err := brainstore.WriteBrainRelativeFileAtomic(brainDir, patternsSkillMemoryPath, buf.Bytes(), 0o600); err != nil {
226			return fmt.Errorf("write skill-memory: %w", err)
227		}
228		return nil
229	}
