12	// path-safety checks (no symlinked brain root, no symlinked path components)
13	// and the atomic writer, creating parent directories as needed.
14	func WriteBrainRelativeFileAtomic(brainDir, rel string, data []byte, perm os.FileMode) error {
15		if err := clibase.RejectSymlinkedBrainRoot(brainDir); err != nil {
16			return err
17		}
18		clean, err := clibase.CleanBrainRelativePath(rel)
19		if err != nil {
20			return err
21		}
22		dir := filepath.Dir(clean)
23		if dir != "." {
24			if err := clibase.RejectExistingSymlinkPathComponents(brainDir, dir); err != nil {
25				return err
26			}
27		}
28		abs := filepath.Join(brainDir, clean)
29		if err := os.MkdirAll(filepath.Dir(abs), 0o700); err != nil {
30			return err
31		}
32		if err := clibase.RejectExistingSymlinkPathComponents(brainDir, clean); err != nil {
33			return err
34		}
35		return WriteFileAtomic(abs, data, perm)
36	}
