38	// RemoveBrainRelativeFile removes a brain-relative file through the same
39	// path-safety checks as the atomic writer. A missing file is not an error.
40	func RemoveBrainRelativeFile(brainDir, rel string) error {
41		if err := clibase.RejectSymlinkedBrainRoot(brainDir); err != nil {
42			return err
43		}
44		clean, err := clibase.CleanBrainRelativePath(rel)
45		if err != nil {
46			return err
47		}
48		if err := clibase.RejectExistingSymlinkPathComponents(brainDir, clean); err != nil {
49			return err
50		}
51		err = os.Remove(filepath.Join(brainDir, clean))
52		if err != nil && !os.IsNotExist(err) {
53			return err
54		}
55		return nil
56	}
