59	// exact inode/file identity observed by a descriptor-bound inventory. Privacy
60	// cleanup uses this after validating content so a raced replacement is never
61	// unlinked under the authority of the original file.
62	func RemoveBrainRelativeFileExpected(brainDir, rel string, expected os.FileInfo) error {
63		if expected == nil {
64			return fmt.Errorf("memory_state_unsafe: missing expected file identity for %s", rel)
65		}
66		if err := clibase.RejectSymlinkedBrainRoot(brainDir); err != nil {
67			return err
68		}
69		clean, err := clibase.CleanBrainRelativePath(rel)
70		if err != nil {
71			return err
72		}
73		if err := clibase.RejectExistingSymlinkPathComponents(brainDir, clean); err != nil {
74			return err
75		}
76		path := filepath.Join(brainDir, clean)
77		current, err := MemoryStateLstat(path)
78		if err != nil {
79			if os.IsNotExist(err) {
80				return fmt.Errorf("memory_state_unsafe: expected file disappeared before removal: %s", filepath.ToSlash(clean))
81			}
